export default function CompanyProfilePage() {
  const rootRef = useRef<HTMLDivElement>(null)

  const injectedOnce = useRef(false)
  useEffect(() => {
    document.documentElement.classList.add('js')
    if (injectedOnce.current) {
      // StrictMode's dev-only double-invoke: the DOM from dangerouslySetInnerHTML
      // persisted through the simulated unmount, so the listeners bound on the
      // first pass are still live — re-running SCRIPTS here would bind them twice.
      return () => { document.documentElement.classList.remove('js') }
    }
    injectedOnce.current = true
    const injected: HTMLScriptElement[] = []
    SCRIPTS.forEach(src => {
      const el = document.createElement('script')
      el.text = src
      document.body.appendChild(el)
      injected.push(el)
    })
    return () => {
      document.documentElement.classList.remove('js')
      injected.forEach(el => el.remove())
    }
  }, [])

  return (
    <>
      <style dangerouslySetInnerHTML={{ __html: CSS }} />
      <div ref={rootRef} dangerouslySetInnerHTML={{ __html: BODY_HTML }} />
    </>
  )
}
